Các phương án với image_prompt nguyên văn và hash: [{"candidate_id": "R4-B1-C1", "batch_id": "B1", "revision": 4, "title": "Váy Liền Thân Lụa Xanh Ngọc Bích - Sắp Xếp Bố Cục Thêu Sen Dọc", "image_prompt": "Thiết kế váy liền thân nữ mùa hè dành cho sự kiện thời trang với chủ đề kết hợp truyền thống và hiện đại. Váy liền thân dáng dài suông nhẹ, thoải mái, dễ mặc, toát lên vẻ sang trọng và bắt kịp xu hướng. Cấu trúc hai lớp tinh tế: lớp trong lụa tơ tằm tự nhiên cao cấp màu trắng ngà mỏng nhẹ có cổ kín cao ôm sát thanh lịch; lớp phủ ngoài bằng lụa tơ tằm tự nhiên cao cấp mỏng nhẹ màu xanh ngọc bích nhạt có thiết kế cổ chữ V khoét sâu, hai cổ thuộc hai lớp khác nhau, giữ dáng váy mùa hè gọn gàng, thoáng mát. Kỹ thuật thêu tay mô-típ hoa sen cách điệu được bố trí dọc theo đường viền cổ chữ V và ngực áo của lớp ngoài. Kết hợp túi xách mây tre đan cách điệu quai ngọc. Bối cảnh sự kiện thời trang mùa hè hiện đại, ánh sáng tự nhiên mềm mại, góc chụp toàn thân sắc nét.", "design_sections": [{"domain_id": "bối_cảnh", "description": "Thiết kế dành cho sự kiện thời trang mùa hè.", "related_atom_ids": ["atom_01"]}, {"domain_id": "văn_hóa", "description": "Chủ đề kết hợp truyền thống và hiện đại, gợi nhắc Việt phục qua phom dáng và cấu trúc cổ áo hai lớp.", "related_atom_ids": ["atom_02", "atom_04", "atom_s3_viet_phuc"]}, {"domain_id": "cấu_trúc", "description": "Dạng váy liền thân nữ hai lớp, xử lý gọn gàng, tiện dụng, thoải mái, dễ mặc.", "related_atom_ids": ["atom_03", "atom_05", "atom_06", "atom_s3_viet_phuc", "atom_s3_materials"]}, {"domain_id": "mỹ_thuật", "description": "Toát lên vẻ sang trọng, bắt kịp xu hướng với bảng màu xanh ngọc bích nhạt phối trắng ngà thanh lịch, thêu tay hoa sen cách điệu và túi xách mây tre đan quai ngọc.", "related_atom_ids": ["atom_05", "atom_07", "atom_s3_materials", "atom_s3_palette", "atom_s3_ornaments", "atom_s3_accessories"]}], "fashion_summary": "Váy liền thân nữ cấu trúc hai lớp gồm lớp trong trắng ngà cổ kín cao và lớp ngoài xanh ngọc bí